-- Spell Battle + bot parity: the Lua port against fixtures generated by the REAL web code
-- (tools/parity/gen-spell-fixtures.ts -> tests/fixtures/spells.lua), plus rule tests.
local root, testdir = ...
local H = dofile(testdir .. "/harness.lua")
local ns = H.load(root, { "Engine/Prng.lua", "Engine/Pieces.lua", "Engine/Engine.lua", "Engine/Input.lua", "Engine/Verify.lua", "Engine/Spells.lua", "Engine/Bot.lua" })
local E, S, Bot = ns.Engine, ns.Spells, ns.Bot
local it, eq, ok, describe = H.it, H.eq, H.ok, H.describe
local fx = dofile(os.getenv("SR_SPELL_FIXTURES") or (testdir .. "/fixtures/spells.lua"))

local function join(t) local o = {} for i, v in ipairs(t) do o[i] = tostring(v) end return table.concat(o, ",") end
local function castsOf(side) local o = {} for _, c in ipairs(side.casts) do o[#o + 1] = c.tick; o[#o + 1] = S.INDEX[c.spell] end return o end
local function invalidOf(side) local o = {} for _, c in ipairs(side.invalidCasts) do o[#o + 1] = c.tick .. ":" .. c.code .. ":" .. c.reason end return o end
local function fxCasts(c) local o = {} for _, x in ipairs(c) do o[#o + 1] = x[1]; o[#o + 1] = x[2] end return o end
local function fxInvalid(c) local o = {} for _, x in ipairs(c) do o[#o + 1] = x[1] .. ":" .. x[2] .. ":" .. x[3] end return o end

local function checkSide(side, want, label)
  eq(E.hashState(side.game), want.hash, label .. " hash")
  eq(side.game.score, want.score, label .. " score")
  eq(side.mana, want.mana, label .. " mana")
  eq(join(castsOf(side)), join(fxCasts(want.casts)), label .. " casts")
  eq(join(invalidOf(side)), join(fxInvalid(want.invalid)), label .. " invalid casts")
  eq(#side.log / 2, want.logLen, label .. " log length")
  eq(side.freezeUntil, want.freezeUntil, label .. " freeze")
  eq(side.speedUntil, want.speedUntil, label .. " speed")
  eq(side.blackoutUntil, want.blackoutUntil, label .. " blackout")
end

describe("spell rules fingerprint (web " .. fx.webCommit:sub(1, 7) .. ")", function()
  local f = fx.fingerprint
  it("same 9 spells, same names, costs, targets, durations and hints", function()
    eq(join(S.SPELLS), join(f.spells))
    for _, id in ipairs(f.spells) do
      local a, b = S.INFO[id], f.info[id]
      eq(a.name, b.name, id); eq(a.cost, b.cost, id .. " cost"); eq(a.target, b.target, id .. " target")
      eq(a.durationTicks, b.durationTicks, id .. " duration")
      eq(a.hint, (b.hint:gsub("\195\151", "\195\151")), id .. " hint")
    end
  end)
  it("same mana, cooldown, delivery delay, cast codes, default loadout, garbage cell", function()
    eq(S.CAST_BASE, f.castBase); eq(S.MANA_MAX, f.manaMax); eq(S.CAST_COOLDOWN_TICKS, f.cooldown)
    eq(S.DELIVERY_TICKS, f.delivery); eq(join(S.DEFAULT_LOADOUT), join(f.defaultLoadout)); eq(E.GARBAGE_CELL, f.garbageCell)
    for l = 0, 5 do for ci, c in ipairs({ 0, 1, 3 }) do eq(S.manaForClear(l, c), f.mana[l + 1][ci], "mana " .. l .. "/" .. c) end end
  end)
  it("same bot profiles (v1 + v2), switch time, loadouts and cast styles", function()
    eq(Bot.V2_FROM_MS, f.v2From)
    for _, d in ipairs(Bot.DIFFICULTIES) do
      for _, k in ipairs({ "label", "thinkTicks", "actionTicks", "topN", "pickBest", "errorRate" }) do
        eq(Bot.PROFILES[d][k], f.profiles[d][k], d .. " v2 " .. k)
        eq(Bot.PROFILES_V1[d][k], f.profilesV1[d][k], d .. " v1 " .. k)
      end
      eq(join(Bot.LOADOUTS[d]), join(f.botLoadouts[d]), d .. " loadout")
    end
    -- cast styles are private in the web module; check them through behaviour (see battles) and text
    for _, d in ipairs(Bot.DIFFICULTIES) do
      ok(f.castStyle[d].every > 0 and f.castStyleV1[d].every > 0)
    end
  end)
end)

describe("classic bot: same decisions as the web bot", function()
  for _, g in ipairs(fx.botGames) do
    it(g.seed .. " (" .. g.difficulty .. ")", function()
      local s = Bot.generateGame(g.seed, g.difficulty, g.untilTick, g.createdAtMs)
      eq(join(s.inputLog), join(g.log), "every input at the same tick")
      eq(s.tick, g.ticks); eq(E.hashState(s), g.hash); eq(s.score, g.score)
    end)
  end
end)

describe("board effects on real boards", function()
  it("bomb cells, worst-fit piece, garbage gap, stack height, bot candidates and every effect's result", function()
    for _, c in ipairs(fx.effects) do
      local function fresh() return E.replay(c.seed, { startLevel = 1 }, c.log, c.untilTick) end
      local st = fresh()
      eq(E.hashState(st), c.stateHash, c.seed .. " state")
      local bc = S.bombCells(st)
      local a, b = {}, {}
      for i, x in ipairs(bc) do a[i] = x[1] .. ":" .. x[2] end
      for i, x in ipairs(c.bomb) do b[i] = x[1] .. ":" .. x[2] end
      eq(join(a), join(b), c.seed .. " bomb cells")
      eq(S.worstFitPiece(st), c.worst, c.seed .. " worst fit")
      eq(S.garbageGap(c.seed, c.castTick, 10), c.gap, c.seed .. " gap")
      eq(Bot.stackHeight(st), c.stackHeight, c.seed .. " stack height")
      local cands = Bot.evaluatePlacements(st)
      eq(#cands, #c.candidates, c.seed .. " candidates")
      for i, w in ipairs(c.candidates) do
        eq(cands[i].rotation .. ":" .. cands[i].x, w[1] .. ":" .. w[2], c.seed .. " candidate " .. i)
        eq(cands[i].score, w[3], c.seed .. " candidate score " .. i)
      end
      local x
      x = fresh(); E.clearCells(x, S.bombCells(x)); eq(E.hashState(x), c.after.bomb, "bomb")
      x = fresh(); E.removeBottomRows(x, 2); eq(E.hashState(x), c.after.lineBlast, "lineBlast")
      x = fresh(); E.clearBoard(x); eq(E.hashState(x), c.after.clearBoard, "clearBoard")
      x = fresh(); E.addGarbage(x, 2, S.garbageGap(c.seed, c.castTick, 10)); eq(E.hashState(x), c.after.garbage, "garbage")
      x = fresh(); E.addGarbage(x, 8, 3); eq(E.hashState(x), c.after.garbage8, "8 garbage rows")
      x = fresh(); E.swapActive(x); eq(E.hashState(x), c.after.swap, "swap")
      x = fresh(); E.replaceNext(x, S.worstFitPiece(x)); eq(E.hashState(x), c.after.scramble, "scramble")
      x = fresh(); E.tick(x, "frozen"); eq(E.hashState(x), c.after.frozen, "frozen tick")
      x = fresh(); E.tick(x, "double"); eq(E.hashState(x), c.after.double, "double tick")
    end
    for _, g in ipairs(fx.gaps) do eq(S.garbageGap(g[1], g[2], 10), g[3], g[1]) end
  end)
end)

describe("full Spell Battles, bot vs bot (lockstep)", function()
  for _, b in ipairs(fx.battles) do
    it(b.seed, function()
      local sim = S.Sim.new(b.seed, {
        { loadout = Bot.LOADOUTS[b.a], actor = Bot.SpellBot.new(b.seed, b.a, b.createdAtMs), untilTick = b.cap },
        { loadout = Bot.LOADOUTS[b.b], actor = Bot.SpellBot.new(b.seed .. ":b", b.b, b.createdAtMs), untilTick = b.cap },
      })
      for _, cp in ipairs(b.checkpoints) do
        while sim.t < cp.t and not sim:done() do sim:step() end
        eq(sim.t, cp.t)
        checkSide(sim.sides[1], cp.a, "t" .. cp.t .. " A")
        checkSide(sim.sides[2], cp.b, "t" .. cp.t .. " B")
      end
      local r = sim:run()
      checkSide(r.sides[1], b.final.a, "final A")
      checkSide(r.sides[2], b.final.b, "final B")
      eq(join(r.sides[1].log), join(b.logA), "log A")
      eq(join(r.sides[2].log), join(b.logB), "log B")
      eq(join(r.bestCombo), join(b.bestCombo))
      -- the same match replayed from the two recorded logs gives the same boards (verification path)
      local re = S.Sim.new(b.seed, {
        { loadout = Bot.LOADOUTS[b.a], log = b.logA, untilTick = b.cap },
        { loadout = Bot.LOADOUTS[b.b], log = b.logB, untilTick = b.cap },
      }):run()
      eq(E.hashState(re.sides[1].game), b.final.a.hash, "replayed A")
      eq(E.hashState(re.sides[2].game), b.final.b.hash, "replayed B")
    end)
  end
end)

local function verifyEq(r, w, label)
  eq(r.ok, w.ok, label .. " ok")
  eq(join(r.reasons), join(w.reasons), label .. " reasons")
  eq(r.score, w.score, label .. " score"); eq(r.lines, w.lines, label .. " lines"); eq(r.level, w.level, label .. " level")
  eq(r.hash, w.hash, label .. " hash"); eq(r.toppedOut, w.toppedOut, label .. " topped out")
  eq(r.mana, w.mana, label .. " mana"); eq(r.casts, w.casts, label .. " casts"); eq(r.bestCombo, w.bestCombo, label .. " best combo")
  local inv = {}
  for _, c in ipairs(r.invalidCasts) do inv[#inv + 1] = c.tick .. ":" .. c.code .. ":" .. c.reason end
  eq(join(inv), join(fxInvalid(w.invalid)), label .. " invalid casts")
end

describe("verifySpellMatch: human logs vs the bot and vs each other", function()
  for _, h in ipairs(fx.humans) do
    it(h.seed .. " (" .. h.difficulty .. ")", function()
      local p1 = { v = 1, seed = h.seed, startLevel = 1, ticks = h.ticks, log = h.log, loadout = h.loadout, elapsedMs = h.elapsedMs }
      local res, botSide = S.verifyMatch({ seed = h.seed, capTicks = 10800, players = { p1 },
        bot = { actor = Bot.SpellBot.new(h.seed, h.difficulty, h.createdAtMs), loadout = Bot.LOADOUTS[h.difficulty] } })
      verifyEq(res[1], h.vsBot, "vs bot")
      checkSide(botSide, h.bot, "bot")
      eq(S.botMatchDecided({ score = res[1].score, gameOver = res[1].toppedOut }, botSide.game), h.decided, "decided")
      local p2 = { v = 1, seed = h.seed, startLevel = 1, ticks = h.ticks2, log = h.log2, loadout = h.loadout2, elapsedMs = h.elapsedMs2 }
      local r2 = S.verifyMatch({ seed = h.seed, capTicks = 10800, players = { p1, p2 } })
      verifyEq(r2[1], h.vsHuman[1], "human 1")
      verifyEq(r2[2], h.vsHuman[2], "human 2")
    end)
  end
end)

describe("verifySpellMatch: tampered logs get the web's verdict", function()
  local names = {}
  for k in pairs(fx.tampered) do names[#names + 1] = k end
  table.sort(names)
  for _, name in ipairs(names) do
    local t = fx.tampered[name]
    it(name .. " -> " .. (#t.result.reasons > 0 and table.concat(t.result.reasons, ", ") or "ok"), function()
      local p = { v = t.v, seed = t.seed, startLevel = t.startLevel, ticks = t.ticks, log = t.log, loadout = t.loadout, elapsedMs = t.elapsedMs }
      local res = S.verifyMatch({ seed = "tamper", capTicks = 10800, players = { p },
        bot = { actor = Bot.SpellBot.new("tamper", "rookie", Bot.V2_FROM_MS + 86400000), loadout = Bot.LOADOUTS.rookie } })
      verifyEq(res[1], t.result, name)
    end)
  end
end)

describe("spell rules (ported from the web's spells.test.ts behaviour)", function()
  local function sideWithMana(seed, loadout, mana)
    local s = S.createSide(seed, loadout or S.DEFAULT_LOADOUT)
    s.mana = mana or 20
    return s
  end
  it("a loadout is 4 distinct spells, exactly 2 self + 2 opponent; encode/decode round-trips", function()
    ok(S.isValidLoadout(S.DEFAULT_LOADOUT))
    ok(not S.isValidLoadout({ "bomb", "swap", "freeze", "garbage" }))
    ok(not S.isValidLoadout({ "bomb", "bomb", "garbage", "blackout" }))
    ok(not S.isValidLoadout({ "bomb", "lineBlast", "garbage" }))
    ok(not S.isValidLoadout({ "bomb", "lineBlast", "garbage", "nope" }))
    ok(not S.isValidLoadout("bomb"))
    eq(join(S.decodeLoadout(S.encodeLoadout(S.DEFAULT_LOADOUT))), join(S.DEFAULT_LOADOUT))
    eq(S.decodeLoadout("0012"), nil); eq(S.decodeLoadout("01"), nil); eq(S.decodeLoadout("0156x"), nil)
  end)
  it("cast costs mana and starts the 3 s cooldown; a second cast inside it is refused", function()
    local s = sideWithMana("c1", nil, 20)
    ok(S.applyCode(s, S.castCode("lineBlast")))
    eq(s.mana, 15)
    ok(not S.applyCode(s, S.castCode("bomb")))
    eq(s.invalidCasts[1].reason, "cooldown")
    for _ = 1, 180 do S.stepSide(s) end
    ok(S.applyCode(s, S.castCode("bomb")))
    eq(s.mana, 11)
  end)
  it("insufficient mana, not in loadout, topped out: no effect, recorded as invalid", function()
    local s = sideWithMana("c2", nil, 3)
    ok(not S.applyCode(s, S.castCode("lineBlast")))
    eq(s.invalidCasts[1].reason, "insufficient_mana")
    s.mana = 20
    ok(not S.applyCode(s, S.castCode("scramble")))
    eq(s.invalidCasts[2].reason, "not_in_loadout")
    s.game.gameOver = true
    ok(not S.applyCode(s, S.castCode("lineBlast")))
    eq(s.invalidCasts[3].reason, "topped_out")
    eq(s.mana, 20, "no mana spent on refused casts")
    ok(not S.applyCode(s, 57)); eq(s.invalidCasts[4].reason, "unknown_code")
  end)
  it("opponent spells are sent with their landing tick (cast tick + 90)", function()
    local s = sideWithMana("c3", nil, 20)
    for _ = 1, 7 do S.stepSide(s) end
    local got
    S.applyCode(s, S.castCode("garbage"), function(inc) got = inc end)
    eq(got.spell, "garbage"); eq(got.castTick, 7); eq(got.at, 97)
  end)
  it("mana comes from clears: 1 / 3 / 5 / 8 plus the combo, capped at 20", function()
    eq(S.manaForClear(1, 0), 1); eq(S.manaForClear(2, 0), 3); eq(S.manaForClear(3, 0), 5); eq(S.manaForClear(4, 0), 8)
    eq(S.manaForClear(4, 3), 11); eq(S.manaForClear(0, 0), 0)
  end)
  it("Freeze stops gravity for 5 s, Speed Up halves the ticks per row for 8 s", function()
    local s = sideWithMana("c4", { "freeze", "bomb", "garbage", "blackout" }, 20)
    local y0 = s.game.active.y
    S.applyCode(s, S.castCode("freeze"))
    for _ = 1, 299 do S.stepSide(s) end
    eq(s.game.active.y, y0, "no fall while frozen")
    eq(S.gravityOf(s), "frozen")
    S.stepSide(s)
    eq(S.gravityOf(s), "normal")
    local t = sideWithMana("c5")
    S.receive(t, { spell = "speedUp", at = 0, castTick = 0 })
    eq(S.gravityOf(t), "double"); eq(t.speedUntil, 480)
  end)
  it("botMatchDecided only when the bot is out, the player is not, and the player leads", function()
    ok(S.botMatchDecided({ score = 10, gameOver = false }, { score = 5, gameOver = true }))
    ok(not S.botMatchDecided({ score = 5, gameOver = false }, { score = 5, gameOver = true }), "level: keep playing")
    ok(not S.botMatchDecided({ score = 4, gameOver = false }, { score = 5, gameOver = true }), "behind")
    ok(not S.botMatchDecided({ score = 10, gameOver = true }, { score = 5, gameOver = true }), "both out")
    ok(not S.botMatchDecided({ score = 10, gameOver = false }, { score = 5, gameOver = false }), "bot alive")
  end)
end)

return H
